\begin{proof}
For $\mathbf{x},\mathbf{y}\in\mathbb{R}^k$, expand the squared norms using the Euclidean inner product:
\[
\begin{aligned}
|\mathbf{x}+\mathbf{y}|^2+|\mathbf{x}-\mathbf{y}|^2
&=(\mathbf{x}+\mathbf{y})\cdot(\mathbf{x}+\mathbf{y})+(\mathbf{x}-\mathbf{y})\cdot(\mathbf{x}-\mathbf{y})\\
&=(|\mathbf{x}|^2+2\mathbf{x}\cdot\mathbf{y}+|\mathbf{y}|^2)
 +( |\mathbf{x}|^2-2\mathbf{x}\cdot\mathbf{y}+|\mathbf{y}|^2)\\
&=2|\mathbf{x}|^2+2|\mathbf{y}|^2.
\end{aligned}
\]
The cross terms cancel, proving the identity.
\end{proof}

\begin{proof}
Let $\mathbf{x},\mathbf{y}\in\mathbb{R}^k$. By bilinearity and symmetry of the Euclidean inner product,
\[
\begin{aligned}
|\mathbf{x}+\mathbf{y}|^2+|\mathbf{x}-\mathbf{y}|^2
&=(\mathbf{x}+\mathbf{y})\cdot(\mathbf{x}+\mathbf{y})+(\mathbf{x}-\mathbf{y})\cdot(\mathbf{x}-\mathbf{y})\\
&=\mathbf{x}\cdot\mathbf{x}+2\mathbf{x}\cdot\mathbf{y}+\mathbf{y}\cdot\mathbf{y}
 +\mathbf{x}\cdot\mathbf{x}-2\mathbf{x}\cdot\mathbf{y}+\mathbf{y}\cdot\mathbf{y}\\
&=2\mathbf{x}\cdot\mathbf{x}+2\mathbf{y}\cdot\mathbf{y}\\
&=2|\mathbf{x}|^2+2|\mathbf{y}|^2.
\end{aligned}
\]
Thus the required identity holds.
\end{proof}

\begin{proof}
Since $\mathbf{x},\mathbf{y}\in\mathbb{R}^k$, their Euclidean norms satisfy $|\mathbf{v}|^2=\mathbf{v}\cdot\mathbf{v}$. Therefore,
\[
\begin{aligned}
|\mathbf{x}+\mathbf{y}|^2+|\mathbf{x}-\mathbf{y}|^2
&=(\mathbf{x}+\mathbf{y})\cdot(\mathbf{x}+\mathbf{y})+(\mathbf{x}-\mathbf{y})\cdot(\mathbf{x}-\mathbf{y})\\
&=\bigl(|\mathbf{x}|^2+2\mathbf{x}\cdot\mathbf{y}+|\mathbf{y}|^2\bigr)
 +\bigl(|\mathbf{x}|^2-2\mathbf{x}\cdot\mathbf{y}+|\mathbf{y}|^2\bigr)\\
&=2|\mathbf{x}|^2+2|\mathbf{y}|^2.
\end{aligned}
\]
Hence the claimed equality is proved.
\end{proof}
